window.__kgRes("data/lessons/13-24.js",{"artifacts":[{"id":"artifact:13/24/skill-catalog-builder","kind":"skill","name":"skill-catalog-builder","text":"---\nname: skill-catalog-builder\ndescription: Build a bounded Agent Skill catalog across explicit discovery scopes and report collisions before loading instruction bodies.\nlicense: MIT\nmetadata:\n  lesson: \"24\"\n---\n\n# Skill catalog builder\n\nUse this skill when an agent host needs deterministic discovery across more than one skill directory.\n\n1. Read `references/discovery-contract.md`.\n2. Review the example host policy in `assets/scope-policy.json`; do not assume its order is universal.\n3. Run `python3 scripts/build_catalog.py project=PATH user=PATH` with scopes listed from highest to lowest precedence.\n4. Inspect the JSON `collisions` and `omitted` arrays before activating a skill.\n5. Load only the selected SKILL.md body. Load a direct reference only when that body names it.\n\nNever execute a bundled script during discovery. Never choose an equal-precedence duplicate by incidental filesystem order.\n\nReturn the catalog budget, selected entries, collision resolutions, and omissions.\n"}],"code":[{"lang":"python","name":"main.py","text":"from __future__ import annotations\n\nimport json\nimport re\nimport tempfile\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path, PurePosixPath\nfrom typing import Iterable\n\n\nFRONTMATTER_LIMIT = 8_192\nNAME_PATTERN = re.compile(r\"^[a-z0-9]+(?:-[a-z0-9]+)*$\")\n\n\n@dataclass(frozen=True)\nclass Scope:\n    name: str\n    root: Path\n\n\n@dataclass(frozen=True)\nclass SkillCandidate:\n    name: str\n    description: str\n    scope: str\n    directory: Path\n    skill_path: Path\n\n\n@dataclass(frozen=True)\nclass CatalogBudget:\n    max_entries: int = 50\n    max_description_chars: int = 240\n    max_catalog_chars: int = 8_000\n\n\n@dataclass(frozen=True)\nclass CatalogEntry:\n    name: str\n    description: str\n    scope: str\n    directory: str\n\n\n@dataclass(frozen=True)\nclass Collision:\n    name: str\n    winner_scope: str\n    shadowed_scopes: tuple[str, ...]\n\n\n@dataclass(frozen=True)\nclass Catalog:\n    entries: tuple[CatalogEntry, ...]\n    collisions: tuple[Collision, ...]\n    omitted: tuple[str, ...]\n    catalog_chars: int\n    report_chars: int\n\n    def model_dict(self) -> dict[str, object]:\n        return {\"entries\": [asdict(entry) for entry in self.entries]}\n\n    def to_dict(self) -> dict[str, object]:\n        return {\n            \"entries\": [asdict(entry) for entry in self.entries],\n            \"collisions\": [asdict(collision) for collision in self.collisions],\n            \"omitted\": list(self.omitted),\n            \"catalog_chars\": self.catalog_chars,\n            \"report_chars\": self.report_chars,\n        }\n\n\nclass DiscoveryError(ValueError):\n    pass\n\n\nclass CollisionError(ValueError):\n    pass\n\n\nclass ReferencePathError(ValueError):\n    pass\n\n\ndef _frontmatter(path: Path) -> dict[str, str]:\n    lines: list[str] = []\n    consumed = 0\n    with path.open(\"r\", encoding=\"utf-8\") as handle:\n        for raw_line in handle:\n            consumed += len(raw_line.encode(\"utf-8\"))\n            if consumed > FRONTMATTER_LIMIT:\n                raise DiscoveryError(f\"frontmatter window exceeded for {path}\")\n            lines.append(raw_line.rstrip(\"\\r\\n\"))\n            if len(lines) > 1 and lines[-1] == \"---\":\n                break\n    if not lines or lines[0] != \"---\" or lines[-1] != \"---\":\n        raise DiscoveryError(f\"invalid frontmatter delimiters in {path}\")\n    end = len(lines) - 1\n    fields: dict[str, str] = {}\n    index = 1\n    while index < end:\n        line = lines[index]\n        if not line.strip() or line.lstrip().startswith(\"#\"):\n            index += 1\n            continue\n        if line[:1].isspace() or \":\" not in line:\n            raise DiscoveryError(f\"malformed top-level line {index + 1} in {path}\")\n        key, value = line.split(\":\", 1)\n        key = key.strip()\n        if not re.fullmatch(r\"[A-Za-z][A-Za-z0-9-]*\", key):\n            raise DiscoveryError(f\"invalid frontmatter field {key!r} in {path}\")\n        if key in fields:\n            raise DiscoveryError(f\"duplicate frontmatter field {key!r} in {path}\")\n        value = value.strip()\n        if key == \"metadata\" and not value:\n            nested: dict[str, str] = {}\n            index += 1\n            while index < end and (not lines[index] or lines[index][:1].isspace()):\n                nested_line = lines[index].strip()\n                if nested_line:\n                    if \":\" not in nested_line:\n                        raise DiscoveryError(\n                            f\"malformed metadata line {index + 1} in {path}\"\n                        )\n                    nested_key, nested_value = nested_line.split(\":\", 1)\n                    nested_key = nested_key.strip()\n                    if (\n                        not re.fullmatch(r\"[A-Za-z][A-Za-z0-9-]*\", nested_key)\n                        or nested_key in nested\n                    ):\n                        raise DiscoveryError(\n                            f\"invalid metadata field {nested_key!r} in {path}\"\n                        )\n                    nested[nested_key] = nested_value.strip().strip(\"\\\"'\")\n                index += 1\n            fields[key] = json.dumps(nested, sort_keys=True)\n            continue\n        if value in {\">\", \"|\"}:\n            block: list[str] = []\n            index += 1\n            while index < end and (not lines[index] or lines[index][:1].isspace()):\n                block.append(lines[index].lstrip())\n                index += 1\n            fields[key] = (\" \" if value == \">\" else \"\\n\").join(block).strip()\n            continue\n        fields[key] = value.strip(\"\\\"'\")\n        index += 1\n    if not fields.get(\"name\") or not fields.get(\"description\"):\n        raise DiscoveryError(f\"name and description are required in {path}\")\n    return fields\n\n\ndef discover_scope(scope: Scope) -> tuple[SkillCandidate, ...]:\n    \"\"\"Read only direct child frontmatter; instruction bodies stay unloaded.\"\"\"\n    if not scope.root.exists():\n        return ()\n    candidates: list[SkillCandidate] = []\n    for directory in sorted(scope.root.iterdir(), key=lambda item: item.name):\n        skill_path = directory / \"SKILL.md\"\n        if not directory.is_dir() or directory.is_symlink():\n            continue\n        if skill_path.is_symlink():\n            raise DiscoveryError(f\"symlinked SKILL.md is not allowed: {skill_path}\")\n        if not skill_path.is_file():\n            continue\n        fields = _frontmatter(skill_path)\n        if len(fields[\"name\"]) > 64 or not NAME_PATTERN.fullmatch(fields[\"name\"]):\n            raise DiscoveryError(\n                f\"frontmatter name {fields['name']!r} is not valid portable kebab-case\"\n            )\n        if len(fields[\"description\"]) > 1024:\n            raise DiscoveryError(f\"description exceeds 1024 characters in {skill_path}\")\n        if fields[\"name\"] != directory.name:\n            raise DiscoveryError(\n                f\"frontmatter name {fields['name']!r} does not match directory {directory.name!r}\"\n            )\n        candidates.append(\n            SkillCandidate(\n                name=fields[\"name\"],\n                description=fields[\"description\"],\n                scope=scope.name,\n                directory=directory.resolve(),\n                skill_path=skill_path.resolve(),\n            )\n        )\n    return tuple(candidates)\n\n\ndef resolve_collisions(\n    candidates: Iterable[SkillCandidate], precedence: tuple[str, ...]\n) -> tuple[tuple[SkillCandidate, ...], tuple[Collision, ...]]:\n    \"\"\"Apply a caller-supplied high-to-low scope order.\"\"\"\n    rank = {scope: index for index, scope in enumerate(precedence)}\n    grouped: dict[str, list[SkillCandidate]] = {}\n    for candidate in candidates:\n        if candidate.scope not in rank:\n            raise CollisionError(f\"scope {candidate.scope!r} is missing from host policy\")\n        grouped.setdefault(candidate.name, []).append(candidate)\n\n    winners: list[SkillCandidate] = []\n    collisions: list[Collision] = []\n    for name in sorted(grouped):\n        options = sorted(\n            grouped[name], key=lambda item: (rank[item.scope], str(item.directory))\n        )\n        top_rank = rank[options[0].scope]\n        tied = [option for option in options if rank[option.scope] == top_rank]\n        if len(tied) > 1:\n            paths = \", \".join(str(option.directory) for option in tied)\n            raise CollisionError(f\"ambiguous {name!r} at equal precedence: {paths}\")\n        winners.append(options[0])\n        if len(options) > 1:\n            collisions.append(\n                Collision(\n                    name=name,\n                    winner_scope=options[0].scope,\n                    shadowed_scopes=tuple(option.scope for option in options[1:]),\n                )\n            )\n    return tuple(winners), tuple(collisions)\n\n\ndef _shorten(text: str, limit: int) -> str:\n    if limit < 1:\n        return \"\"\n    if len(text) <= limit:\n        return text\n    if limit == 1:\n        return \"…\"\n    return text[: limit - 1].rstrip() + \"…\"\n\n\ndef build_catalog(\n    candidates: Iterable[SkillCandidate],\n    precedence: tuple[str, ...],\n    budget: CatalogBudget,\n) -> Catalog:\n    if min(budget.max_entries, budget.max_description_chars, budget.max_catalog_chars) < 1:\n        raise ValueError(\"catalog budgets must be positive\")\n    winners, collisions = resolve_collisions(candidates, precedence)\n    rank = {scope: index for index, scope in enumerate(precedence)}\n    ordered = sorted(winners, key=lambda item: (rank[item.scope], item.name))\n    entries = [\n        CatalogEntry(\n            name=candidate.name,\n            description=_shorten(candidate.description, budget.max_description_chars),\n            scope=candidate.scope,\n            directory=str(candidate.directory),\n        )\n        for candidate in ordered[: budget.max_entries]\n    ]\n    omitted = [candidate.name for candidate in ordered[budget.max_entries :]]\n\n    def model_size(current_entries: list[CatalogEntry]) -> int:\n        payload = {\"entries\": [asdict(entry) for entry in current_entries]}\n        return len(json.dumps(payload, sort_keys=True, separators=(\",\", \":\")))\n\n    used = model_size(entries)\n    while used > budget.max_catalog_chars and entries:\n        removed = entries.pop()\n        omitted.insert(0, removed.name)\n        used = model_size(entries)\n    if used > budget.max_catalog_chars:\n        raise ValueError(\"model-facing catalog exceeds max_catalog_chars\")\n\n    report_chars = 0\n    while True:\n        report = Catalog(\n            tuple(entries), collisions, tuple(omitted), used, report_chars\n        )\n        measured = len(\n            json.dumps(report.to_dict(), sort_keys=True, separators=(\",\", \":\"))\n        )\n        if measured == report_chars:\n            return report\n        report_chars = measured\n\n\ndef _candidate_for(entry: CatalogEntry, candidates: Iterable[SkillCandidate]) -> SkillCandidate:\n    for candidate in candidates:\n        if candidate.name == entry.name and str(candidate.directory) == entry.directory:\n            return candidate\n    raise KeyError(f\"catalog entry {entry.name!r} has no matching candidate\")\n\n\ndef load_skill_body(\n    entry: CatalogEntry,\n    candidates: Iterable[SkillCandidate],\n    max_chars: int = 12_000,\n) -> str:\n    candidate = _candidate_for(entry, candidates)\n    text = candidate.skill_path.read_text(encoding=\"utf-8\")\n    lines = text.splitlines()\n    end = lines.index(\"---\", 1)\n    body = \"\\n\".join(lines[end + 1 :]).strip()\n    if len(body) > max_chars:\n        raise DiscoveryError(f\"skill body exceeds {max_chars} characters\")\n    return body\n\n\ndef validate_reference(skill_directory: Path, reference: str) -> Path:\n    \"\"\"Allow a direct file or one subdirectory, never traversal or deep chains.\"\"\"\n    if not isinstance(reference, str):\n        raise ReferencePathError(\"reference must be a string\")\n    if \"\\\\\" in reference:\n        raise ReferencePathError(\"references must use portable forward slashes\")\n    relative = PurePosixPath(reference)\n    if relative.is_absolute() or any(part in {\"\", \".\", \"..\"} for part in relative.parts):\n        raise ReferencePathError(\"reference must be a clean relative path\")\n    if len(relative.parts) > 2:\n        raise ReferencePathError(\"reference may be at most one directory deep\")\n    root = skill_directory.resolve()\n    unresolved = root\n    for part in relative.parts:\n        unresolved = unresolved / part\n        if unresolved.is_symlink():\n            raise ReferencePathError(\"reference path cannot contain symlinks\")\n    target = unresolved.resolve()\n    if target == root or root not in target.parents:\n        raise ReferencePathError(\"reference escapes the skill directory\")\n    if not target.is_file():\n        raise ReferencePathError(\"reference must resolve to a regular file\")\n    return target\n\n\ndef load_reference(\n    entry: CatalogEntry,\n    reference: str,\n    max_chars: int = 12_000,\n) -> str:\n    target = validate_reference(Path(entry.directory), reference)\n    content = target.read_text(encoding=\"utf-8\")\n    if len(content) > max_chars:\n        raise ReferencePathError(f\"reference exceeds {max_chars} characters\")\n    return content\n\n\ndef _write_skill(root: Path, name: str, description: str, body: str) -> None:\n    directory = root / name\n    (directory / \"references\").mkdir(parents=True)\n    (directory / \"SKILL.md\").write_text(\n        f\"---\\nname: {name}\\ndescription: {description}\\n---\\n\\n{body}\\n\",\n        encoding=\"utf-8\",\n    )\n    (directory / \"references\" / \"format.md\").write_text(\n        \"# Format\\n\\nReturn JSON with an evidence array.\\n\", encoding=\"utf-8\"\n    )\n\n\ndef demo() -> None:\n    with tempfile.TemporaryDirectory(prefix=\"lesson-24-\") as temp_dir:\n        base = Path(temp_dir)\n        user_root = base / \"user\"\n        project_root = base / \"project\"\n        _write_skill(\n            user_root,\n            \"evidence-report\",\n            \"Create a general evidence report when findings need citations.\",\n            \"# Evidence report\\n\\nRead `references/format.md` when formatting the result.\",\n        )\n        _write_skill(\n            project_root,\n            \"evidence-report\",\n            \"Create this project's evidence report when an audit completes.\",\n            \"# Project evidence report\\n\\nRead `references/format.md` for the schema.\",\n        )\n        _write_skill(\n            user_root,\n            \"meeting-brief\",\n            \"Prepare a meeting brief from supplied notes.\",\n            \"# Meeting brief\\n\\nSeparate decisions from open questions.\",\n        )\n        candidates = (\n            *discover_scope(Scope(\"project\", project_root)),\n            *discover_scope(Scope(\"user\", user_root)),\n        )\n        catalog = build_catalog(\n            candidates,\n            precedence=(\"project\", \"user\"),\n            budget=CatalogBudget(max_entries=10, max_catalog_chars=2_000),\n        )\n        selected = next(entry for entry in catalog.entries if entry.name == \"evidence-report\")\n        body = load_skill_body(selected, candidates)\n        reference = load_reference(selected, \"references/format.md\")\n        result = {\n            \"catalog\": catalog.to_dict(),\n            \"disclosure\": {\n                \"level_1_catalog_chars\": catalog.catalog_chars,\n                \"level_2_body_chars\": len(body),\n                \"level_3_reference_chars\": len(reference),\n            },\n        }\n    print(json.dumps(result, indent=2, sort_keys=True))\n\n\nif __name__ == \"__main__\":\n    demo()\n"},{"lang":"python","name":"tests/test_main.py","text":"\"\"\"Deterministic tests for Lesson 24 discovery and disclosure.\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nimport tempfile\nimport unittest\nimport importlib.util\nimport json\nfrom pathlib import Path\n\n\nsys.dont_write_bytecode = True\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\n\nfrom main import (\n    CatalogBudget,\n    CollisionError,\n    DiscoveryError,\n    ReferencePathError,\n    Scope,\n    build_catalog,\n    discover_scope,\n    load_reference,\n    load_skill_body,\n    resolve_collisions,\n    validate_reference,\n)\n\n\ndef write_skill(root: Path, directory: str, description: str = \"Use for reports.\") -> None:\n    skill = root / directory\n    (skill / \"references\").mkdir(parents=True)\n    (skill / \"SKILL.md\").write_text(\n        f\"---\\nname: {directory}\\ndescription: {description}\\n---\\n\\n# Body\\n\\nBODY-MARKER\\n\",\n        encoding=\"utf-8\",\n    )\n    (skill / \"references\" / \"format.md\").write_text(\"FORMAT-MARKER\", encoding=\"utf-8\")\n\n\nclass DiscoveryTests(unittest.TestCase):\n    def setUp(self) -> None:\n        self.temp = tempfile.TemporaryDirectory()\n        self.base = Path(self.temp.name)\n\n    def tearDown(self) -> None:\n        self.temp.cleanup()\n\n    def test_discovers_only_direct_skill_directories(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        (root / \"not-a-skill\").mkdir()\n        candidates = discover_scope(Scope(\"project\", root))\n        self.assertEqual([candidate.name for candidate in candidates], [\"reporter\"])\n\n    def test_discovers_folded_description_content(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        skill_path = root / \"reporter\" / \"SKILL.md\"\n        skill_path.write_text(\n            \"\"\"---\nname: reporter\ndescription: >\n  Build an evidence report when an audit\n  needs a bounded summary.\nmetadata:\n  owner: platform\n---\nBody\n\"\"\",\n            encoding=\"utf-8\",\n        )\n        candidate = discover_scope(Scope(\"project\", root))[0]\n        self.assertEqual(\n            candidate.description,\n            \"Build an evidence report when an audit needs a bounded summary.\",\n        )\n\n    def test_rejects_frontmatter_name_directory_mismatch(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        skill_path = root / \"reporter\" / \"SKILL.md\"\n        skill_path.write_text(\n            skill_path.read_text(encoding=\"utf-8\").replace(\n                \"name: reporter\", \"name: different-name\"\n            ),\n            encoding=\"utf-8\",\n        )\n        with self.assertRaises(DiscoveryError):\n            discover_scope(Scope(\"project\", root))\n\n    def test_rejects_invalid_or_duplicate_identity_fields(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"Bad_Name\")\n        with self.assertRaises(DiscoveryError):\n            discover_scope(Scope(\"project\", root))\n        skill_path = root / \"Bad_Name\" / \"SKILL.md\"\n        skill_path.write_text(\n            \"---\\nname: Bad_Name\\nname: Bad_Name\\ndescription: Duplicate.\\n---\\nBody\\n\",\n            encoding=\"utf-8\",\n        )\n        with self.assertRaises(DiscoveryError):\n            discover_scope(Scope(\"project\", root))\n\n    def test_rejects_malformed_top_level_frontmatter(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        skill_path = root / \"reporter\" / \"SKILL.md\"\n        skill_path.write_text(\n            skill_path.read_text(encoding=\"utf-8\").replace(\n                \"description: Use for reports.\",\n                \"this is not yaml\\ndescription: Use for reports.\",\n            ),\n            encoding=\"utf-8\",\n        )\n        with self.assertRaisesRegex(DiscoveryError, \"malformed top-level\"):\n            discover_scope(Scope(\"project\", root))\n\n    def test_rejects_symlinked_skill_file(self) -> None:\n        root = self.base / \"scope\"\n        directory = root / \"reporter\"\n        directory.mkdir(parents=True)\n        source = self.base / \"external-skill.md\"\n        source.write_text(\n            \"---\\nname: reporter\\ndescription: Report findings.\\n---\\nBody\\n\",\n            encoding=\"utf-8\",\n        )\n        (directory / \"SKILL.md\").symlink_to(source)\n        with self.assertRaises(DiscoveryError):\n            discover_scope(Scope(\"project\", root))\n\n    def test_host_precedence_selects_project_candidate(self) -> None:\n        project = self.base / \"project\"\n        user = self.base / \"user\"\n        write_skill(project, \"reporter\", \"Project report.\")\n        write_skill(user, \"reporter\", \"User report.\")\n        candidates = (*discover_scope(Scope(\"project\", project)), *discover_scope(Scope(\"user\", user)))\n        winners, collisions = resolve_collisions(candidates, (\"project\", \"user\"))\n        self.assertEqual(winners[0].scope, \"project\")\n        self.assertEqual(collisions[0].shadowed_scopes, (\"user\",))\n\n    def test_precedence_is_policy_not_fixed_standard(self) -> None:\n        project = self.base / \"project\"\n        user = self.base / \"user\"\n        write_skill(project, \"reporter\")\n        write_skill(user, \"reporter\")\n        candidates = (*discover_scope(Scope(\"project\", project)), *discover_scope(Scope(\"user\", user)))\n        winners, _ = resolve_collisions(candidates, (\"user\", \"project\"))\n        self.assertEqual(winners[0].scope, \"user\")\n\n    def test_equal_precedence_collision_is_not_silently_overwritten(self) -> None:\n        first = self.base / \"first\"\n        second = self.base / \"second\"\n        write_skill(first, \"reporter\")\n        write_skill(second, \"reporter\")\n        candidates = (*discover_scope(Scope(\"project\", first)), *discover_scope(Scope(\"project\", second)))\n        with self.assertRaises(CollisionError):\n            resolve_collisions(candidates, (\"project\",))\n\n    def test_catalog_honors_entry_budget(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"alpha\")\n        write_skill(root, \"beta\")\n        catalog = build_catalog(\n            discover_scope(Scope(\"project\", root)),\n            (\"project\",),\n            CatalogBudget(max_entries=1, max_catalog_chars=2_000),\n        )\n        self.assertEqual([entry.name for entry in catalog.entries], [\"alpha\"])\n        self.assertEqual(catalog.omitted, (\"beta\",))\n\n    def test_catalog_truncates_description_to_declared_budget(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\", \"x\" * 30)\n        catalog = build_catalog(\n            discover_scope(Scope(\"project\", root)),\n            (\"project\",),\n            CatalogBudget(max_description_chars=10, max_catalog_chars=2_000),\n        )\n        self.assertEqual(len(catalog.entries[0].description), 10)\n        self.assertTrue(catalog.entries[0].description.endswith(\"…\"))\n\n    def test_catalog_budget_covers_exact_model_facing_entries(self) -> None:\n        root = self.base / \"scope\"\n        for name in (\"alpha\", \"beta\", \"gamma\", \"delta\"):\n            write_skill(root, name, \"x\" * 120)\n        catalog = build_catalog(\n            discover_scope(Scope(\"project\", root)),\n            (\"project\",),\n            CatalogBudget(max_entries=4, max_description_chars=80, max_catalog_chars=700),\n        )\n        model_serialized = json.dumps(\n            catalog.model_dict(), sort_keys=True, separators=(\",\", \":\")\n        )\n        report_serialized = json.dumps(\n            catalog.to_dict(), sort_keys=True, separators=(\",\", \":\")\n        )\n        self.assertEqual(len(model_serialized), catalog.catalog_chars)\n        self.assertLessEqual(len(model_serialized), 700)\n        self.assertEqual(len(report_serialized), catalog.report_chars)\n\n    def test_diagnostics_do_not_evict_model_visible_entries(self) -> None:\n        project = self.base / \"project\"\n        user = self.base / \"user\"\n        for name in (\"alpha\", \"beta\", \"gamma\"):\n            write_skill(project, name, \"Project report.\")\n            write_skill(user, name, \"User report.\")\n        project_candidates = discover_scope(Scope(\"project\", project))\n        baseline = build_catalog(\n            project_candidates,\n            (\"project\", \"user\"),\n            CatalogBudget(max_entries=3, max_catalog_chars=4_000),\n        )\n        combined = build_catalog(\n            (*project_candidates, *discover_scope(Scope(\"user\", user))),\n            (\"project\", \"user\"),\n            CatalogBudget(max_entries=3, max_catalog_chars=baseline.catalog_chars),\n        )\n        self.assertEqual(\n            [entry.name for entry in combined.entries], [\"alpha\", \"beta\", \"gamma\"]\n        )\n        self.assertEqual(combined.catalog_chars, baseline.catalog_chars)\n        self.assertGreater(combined.report_chars, baseline.report_chars)\n\n    def test_body_load_is_separate_from_catalog_construction(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        candidates = discover_scope(Scope(\"project\", root))\n        catalog = build_catalog(candidates, (\"project\",), CatalogBudget())\n        self.assertNotIn(\"BODY-MARKER\", str(catalog.to_dict()))\n        self.assertIn(\"BODY-MARKER\", load_skill_body(catalog.entries[0], candidates))\n\n    def test_accepts_one_level_reference(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        path = validate_reference(root / \"reporter\", \"references/format.md\")\n        self.assertEqual(path.name, \"format.md\")\n\n    def test_rejects_traversal_reference(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        with self.assertRaises(ReferencePathError):\n            validate_reference(root / \"reporter\", \"../secret.md\")\n\n    def test_rejects_non_string_reference_with_domain_error(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        for reference in (None, 1, [], {}):\n            with self.subTest(reference=reference):\n                with self.assertRaisesRegex(ReferencePathError, \"must be a string\"):\n                    validate_reference(root / \"reporter\", reference)\n\n    def test_rejects_deep_reference_chain(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        with self.assertRaises(ReferencePathError):\n            validate_reference(root / \"reporter\", \"references/archive/format.md\")\n\n    def test_rejects_internal_symlink_reference(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        link = root / \"reporter\" / \"references\" / \"linked.md\"\n        link.symlink_to(link.parent / \"format.md\")\n        with self.assertRaisesRegex(ReferencePathError, \"symlinks\"):\n            validate_reference(root / \"reporter\", \"references/linked.md\")\n\n    def test_reference_load_obeys_size_budget(self) -> None:\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        candidates = discover_scope(Scope(\"project\", root))\n        catalog = build_catalog(candidates, (\"project\",), CatalogBudget())\n        with self.assertRaises(ReferencePathError):\n            load_reference(catalog.entries[0], \"references/format.md\", max_chars=3)\n\n    def test_bundled_catalog_reports_equal_precedence_duplicate(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-catalog-builder\"\n            / \"scripts\"\n            / \"build_catalog.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_catalog\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        first = self.base / \"first\"\n        second = self.base / \"second\"\n        write_skill(first, \"reporter\")\n        write_skill(second, \"reporter\")\n        result = module.build([(\"project\", first), (\"project\", second)], 40)\n        self.assertFalse(result[\"valid\"])\n        self.assertIn(\"equal-precedence duplicate\", result[\"errors\"][0])\n\n    def test_bundled_catalog_shorten_handles_boundary_limits(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-catalog-builder\"\n            / \"scripts\"\n            / \"build_catalog.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_catalog_shorten\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        self.assertEqual(module.shorten(\"catalog\", -1), \"\")\n        self.assertEqual(module.shorten(\"catalog\", 0), \"\")\n        self.assertEqual(module.shorten(\"catalog\", 1), \"…\")\n\n    def test_bundled_catalog_rejects_malformed_top_level_frontmatter(self) -> None:\n        script_path = (\n            Path(__file__).resolve().parents[2]\n            / \"outputs\"\n            / \"skill-catalog-builder\"\n            / \"scripts\"\n            / \"build_catalog.py\"\n        )\n        spec = importlib.util.spec_from_file_location(\"bundled_strict_catalog\", script_path)\n        self.assertIsNotNone(spec)\n        self.assertIsNotNone(spec.loader)\n        module = importlib.util.module_from_spec(spec)\n        spec.loader.exec_module(module)\n        root = self.base / \"scope\"\n        write_skill(root, \"reporter\")\n        skill_path = root / \"reporter\" / \"SKILL.md\"\n        skill_path.write_text(\n            skill_path.read_text(encoding=\"utf-8\").replace(\n                \"description: Use for reports.\",\n                \"this is not yaml\\ndescription: Use for reports.\",\n            ),\n            encoding=\"utf-8\",\n        )\n        result = module.build([(\"project\", root)], 40)\n        self.assertFalse(result[\"valid\"])\n        self.assertTrue(any(\"malformed top-level\" in error for error in result[\"errors\"]))\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"}],"figures":["figures-agent-skills.js"],"html":"<h2 id=\"learning-objectives\">Learning Objectives</h2>\n<ul>\n<li>Build a filesystem discovery pipeline that separates scope, validation, collision policy, and catalog publication.</li>\n<li>Explain the three disclosure levels: catalog metadata, active instructions, and task-specific resources.</li>\n<li>Design references so an agent can reach required detail directly without loading the entire package.</li>\n<li>Budget catalog space independently from active-skill context.</li>\n<li>Reject path traversal and symlink escape when a skill reads its own resources.</li>\n</ul>\n<h2 id=\"the-problem\">The Problem</h2>\n<p>Your agent has 200 installed skills. Loading every <code>SKILL.md</code>, reference file, script, and template at session start would bury the current task in unrelated procedure. Loading nothing would force the user to remember exact filesystem paths.</p>\n<p>The usual compromise is a catalog: show the model a compact identity and routing description for each eligible skill, then load the full body only after selection. That creates two new engineering problems.</p>\n<p>First, discovery is not just recursive file search. Skills can exist at project, user, administrator, plugin, or built-in scopes. Two packages can share a name. A symlink can point outside the trusted root. A malformed package can consume catalog space or become impossible to invoke.</p>\n<p>Second, progressive disclosure can become progressive confusion. If <code>SKILL.md</code> says &quot;read the relevant guide&quot; and the package contains twelve guides, the model must guess. If every guide points to three more files, loading becomes an unbounded graph walk.</p>\n<p>A good runtime makes discovery deterministic and disclosure intentional.</p>\n<h2 id=\"the-concept\">The Concept</h2>\n<h3 id=\"discovery-is-a-compiler-pipeline\">Discovery is a compiler pipeline</h3>\n<p>Treat the filesystem as source input. Do not publish raw paths directly to the model.</p>\n<div class=\"lesson-figure\" data-figure=\"skill-discovery-pipeline\"></div>\n<p>Each stage should produce structured data and structured failures. A discovery log should answer:</p>\n<ul>\n<li>Which roots were searched?</li>\n<li>Which candidates were found?</li>\n<li>Which candidates were rejected, and why?</li>\n<li>Which package won a collision?</li>\n<li>Which catalog entries were shortened or omitted because of budget?</li>\n</ul>\n<p>Without that evidence, &quot;the model did not use my skill&quot; is almost impossible to diagnose.</p>\n<h3 id=\"scope-is-runtime-policy\">Scope is runtime policy</h3>\n<p>The portable specification defines a skill package, not one universal installation path or precedence order. The host decides where it searches.</p>\n<p>A generic runtime might use these scopes:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Scope</th><th>Example root</th><th>Intended ownership</th></tr></thead><tbody><tr><td>Workspace</td><td><code>&lt;repo&gt;/.agents/skills/</code></td><td>Project maintainers</td></tr><tr><td>User</td><td><code>&lt;user-data&gt;/skills/</code></td><td>One developer</td></tr><tr><td>Administrator</td><td><code>&lt;system&gt;/skills/</code></td><td>Machine or organization policy</td></tr><tr><td>Plugin</td><td>A signed plugin bundle</td><td>Plugin publisher and installer</td></tr><tr><td>Built-in</td><td>Runtime package</td><td>Runtime vendor</td></tr></tbody></table></div>\n<p>As of August 2026, Codex documents project discovery from <code>$CWD/.agents/skills</code> through ancestor directories up to the repository root, plus user, administrator, and built-in locations. It supports symlinked skill directories. Duplicate names may both appear rather than being merged. Those are Codex behaviors, not requirements of <code>SKILL.md</code>; verify the current <a href=\"https://learn.chatgpt.com/docs/build-skills\" target=\"_blank\" rel=\"noopener\">Codex skill documentation</a> when writing an adapter.</p>\n<p>Never invent precedence from directory names. Declare it as policy and test it. The lesson lab uses an explicit integer rank for each <code>Scope</code> so the same candidate set always resolves the same way.</p>\n<h3 id=\"collisions-need-identity-beyond-name\">Collisions need identity beyond <code>name</code></h3>\n<p>Two packages named <code>release-readiness</code> can be legitimate. One may be a workspace override and one a user default. A catalog entry therefore needs at least:</p>\n<pre class=\"code\" data-lang=\"json\"><code>{\n  &quot;name&quot;: &quot;release-readiness&quot;,\n  &quot;description&quot;: &quot;Inspect a release candidate for this repository.&quot;,\n  &quot;scope&quot;: &quot;workspace&quot;,\n  &quot;source&quot;: &quot;/repo/.agents/skills/release-readiness&quot;,\n  &quot;selected&quot;: true\n}</code></pre>\n<p>Common collision policies include:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Policy</th><th>Benefit</th><th>Risk</th></tr></thead><tbody><tr><td>Keep every candidate</td><td>Nothing is hidden</td><td>The model sees ambiguous names</td></tr><tr><td>Highest-precedence scope wins</td><td>Simple invocation</td><td>A local package can shadow a trusted one</td></tr><tr><td>Reject duplicates</td><td>No silent shadowing</td><td>Legitimate overrides stop working</td></tr><tr><td>Qualify names by source</td><td>Explicit identity</td><td>User-facing names become longer</td></tr></tbody></table></div>\n<p>Choose one policy for the host. Preserve the rejected or shadowed candidates in diagnostics even when they are absent from the model catalog.</p>\n<h3 id=\"three-disclosure-levels\">Three disclosure levels</h3>\n<p>The Agent Skills specification describes staged loading. The key is that each level has a different purpose.</p>\n<div class=\"lesson-figure\" data-figure=\"skill-disclosure-levels\"></div>\n<h4 id=\"level-1-catalog-metadata\">Level 1: catalog metadata</h4>\n<p>The model needs enough information to distinguish the skill from neighbors. The specification estimates roughly 100 tokens per catalog entry, but actual serialization and tokenization belong to the host.</p>\n<p>A useful description has two clauses:</p>\n<pre class=\"code\" data-lang=\"yaml\"><code>description: Validate a release candidate and produce a readiness report. Use when the user asks whether a version, tag, or package is ready to publish.</code></pre>\n<p>The first clause states the capability. The second states the trigger boundary. Lesson 25 evaluates this boundary with positive and near-miss prompts.</p>\n<h4 id=\"level-2-active-instructions\">Level 2: active instructions</h4>\n<p>After activation, the body should function as a map and a procedure. The specification recommends keeping <code>SKILL.md</code> under 500 lines. That is a design signal, not a target to fill.</p>\n<p>The body should contain:</p>\n<ul>\n<li>the task boundary;</li>\n<li>the default workflow;</li>\n<li>branch conditions;</li>\n<li>direct references to deeper files;</li>\n<li>tool and script contracts;</li>\n<li>failure and stopping behavior;</li>\n<li>the expected output and its verification.</li>\n</ul>\n<p>Do not move the central workflow into a reference merely to make the entry file short. Activation must give the model enough context to begin correctly.</p>\n<h4 id=\"level-3-supporting-resources\">Level 3: supporting resources</h4>\n<p>References supply prose or data. Scripts provide deterministic computation. Assets are copied, filled, or transformed into deliverables rather than treated as instructions.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Directory</th><th class=\"al-center\">Model reads it?</th><th class=\"al-center\">Model executes it?</th><th>Typical content</th></tr></thead><tbody><tr><td><code>references/</code></td><td class=\"al-center\">Yes, when needed</td><td class=\"al-center\">No</td><td>schemas, policies, domain guides</td></tr><tr><td><code>scripts/</code></td><td class=\"al-center\">May inspect it</td><td class=\"al-center\">Through a permitted tool</td><td>validators, converters, collectors</td></tr><tr><td><code>assets/</code></td><td class=\"al-center\">Only if useful</td><td class=\"al-center\">No</td><td>templates, fixtures, images, starter files</td></tr></tbody></table></div>\n<p>These names are conventions, not magic capabilities. The host still needs file access and an execution tool.</p>\n<h3 id=\"branch-specific-references-beat-topic-dumps\">Branch-specific references beat topic dumps</h3>\n<p>Write the entry file as a decision map:</p>\n<pre class=\"code\" data-lang=\"markdown\"><code>## Choose the path\n\n- For a Python package, read `references/python-release.md`.\n- For a container image, read `references/container-release.md`.\n- For a documentation-only release, read `references/docs-release.md`.\n- If the release combines artifact types, read only the guides for those artifacts.</code></pre>\n<p>This gives every reference an observable load condition. &quot;Read <code>references/</code> for more&quot; does not.</p>\n<p>Keep the reference graph shallow. The official guidance recommends direct links from <code>SKILL.md</code> and avoiding deep chains. One hop makes reachability testable and reduces the chance that a needed constraint never enters context.</p>\n<div class=\"lesson-figure\" data-figure=\"skill-reference-map\"></div>\n<h3 id=\"catalog-budget-and-active-context-are-different-budgets\">Catalog budget and active context are different budgets</h3>\n<p>Let <code>c_i</code> be the serialized catalog cost of skill <code>i</code>, <code>B_c</code> the catalog budget, <code>b_j</code> the active body cost, and <code>r_k</code> the resources actually loaded.</p>\n<pre class=\"code\" data-lang=\"text\"><code>catalog_cost = sum(c_i for every published skill)\nactive_cost = sum(b_j for every activated skill) + sum(r_k for every disclosed resource)</code></pre>\n<p>Reducing one budget does not automatically reduce the other. Short descriptions can save catalog space while an activated 900-line body still overwhelms the task. Splitting the body into references can reduce active cost only when the runtime and instructions actually avoid loading irrelevant branches.</p>\n<p>Codex currently budgets the initial skill list at 2 percent of the context\nwindow when the context-window size is known. The 8,000-character value is a\nfallback only when that size is unknown; it is not a second cap combined with\nthe 2 percent rule. When the catalog exceeds the applicable budget,\ndescriptions may be shortened or omitted. Treat those figures as current\nCodex policy, not a property of the Agent Skills standard.</p>\n<h3 id=\"resource-paths-are-a-trust-boundary\">Resource paths are a trust boundary</h3>\n<p>A skill should read only files inside its package. Literal string-prefix checks are not enough:</p>\n<pre class=\"code\" data-lang=\"text\"><code>references/../../../../.ssh/config\nreferences/external-link -&gt; /private/company-secrets</code></pre>\n<p>Resolve the package root and candidate with filesystem semantics, reject absolute inputs, and verify that the resolved candidate remains under the resolved root. Decide whether symlinks are allowed before discovery. If allowed, check the resolved target every time.</p>\n<div class=\"lesson-figure\" data-figure=\"skill-resource-containment\"></div>\n<p>Path containment does not establish content trust. A valid in-package reference can still contain malicious instructions. Lesson 26 handles that threat.</p>\n<h3 id=\"loading-must-be-observable\">Loading must be observable</h3>\n<p>Record disclosure events without logging secrets:</p>\n<pre class=\"code\" data-lang=\"json\"><code>{\n  &quot;event&quot;: &quot;skill.resource.loaded&quot;,\n  &quot;skill&quot;: &quot;release-readiness&quot;,\n  &quot;resource&quot;: &quot;references/python-release.md&quot;,\n  &quot;reason&quot;: &quot;candidate contains pyproject.toml&quot;,\n  &quot;bytes&quot;: 2840\n}</code></pre>\n<p>The reason turns a context choice into reviewable evidence. It also helps identify instructions that cause the agent to load every file &quot;just in case.&quot;</p>\n<h2 id=\"build-it\">Build It</h2>\n<p><code>code/main.py</code> builds a deterministic discovery and disclosure engine.</p>\n<p>The discovery surface includes:</p>\n<ul>\n<li><code>Scope</code> for source and precedence metadata;</li>\n<li><code>SkillCandidate</code> for an unvalidated filesystem candidate;</li>\n<li><code>discover_scope(scope)</code> to enumerate immediate skill directories;</li>\n<li><code>resolve_collisions(candidates, precedence)</code> to apply one declared policy;</li>\n<li><code>CatalogEntry</code> and <code>build_catalog(...)</code> to publish bounded metadata;</li>\n<li><code>CatalogBudget</code> to account for serialized entries without pretending characters are universal tokens.</li>\n</ul>\n<p>The disclosure surface includes:</p>\n<ul>\n<li><code>load_skill_body(entry, ...)</code> for Level 2 activation;</li>\n<li><code>validate_reference(skill_dir, reference)</code> for path containment;</li>\n<li><code>load_reference(...)</code> for bounded Level 3 reads.</li>\n</ul>\n<p>Run the lab:</p>\n<pre class=\"code\" data-lang=\"bash\"><code>cd &quot;$(git rev-parse --show-toplevel)&quot;\ncd phases/13-tools-and-protocols/24-skill-discovery-and-progressive-disclosure\npython3 code/main.py\npython3 -m unittest discover -s code/tests -v</code></pre>\n<p>This block requires a local clone and resolves the repository root from any\nworking directory inside that clone.</p>\n<p>The demo creates temporary project and user scopes, inserts a collision, builds a catalog under a deliberately small budget, activates one skill, and attempts both a valid reference read and a traversal escape. No permanent files are installed.</p>\n<h3 id=\"why-discovery-is-shallow\">Why discovery is shallow</h3>\n<p><code>discover_scope</code> checks immediate child directories for <code>SKILL.md</code>. It does not recursively treat every nested <code>SKILL.md</code> as a separate package. This preserves the package boundary and avoids accidentally publishing examples or fixtures inside an installed skill.</p>\n<h3 id=\"why-the-lab-does-not-parse-arbitrary-yaml\">Why the lab does not parse arbitrary YAML</h3>\n<p>The lab supports the scalar frontmatter needed for its catalog. A production runtime should use a safe YAML parser with an explicit schema, size limits, and disabled custom object construction. &quot;Stdlib-only&quot; is a teaching constraint, not permission to invent a partial YAML dialect silently.</p>\n<h2 id=\"use-it\">Use It</h2>\n<p>Apply this checklist to any discovery adapter:</p>\n<ol>\n<li>List every configured root and who can write to it.</li>\n<li>State whether symlinked packages are allowed.</li>\n<li>Validate package name, directory name, required metadata, and entry-body size.</li>\n<li>Preserve source and scope in the internal identity.</li>\n<li>Declare and test duplicate-name behavior.</li>\n<li>Measure the exact serialized catalog sent to the model.</li>\n<li>Record why a body or resource was loaded.</li>\n<li>Keep resource reads inside the resolved package root.</li>\n<li>Fail clearly when a referenced file is missing.</li>\n<li>Rebuild the catalog when installations or policies change.</li>\n</ol>\n<h2 id=\"ship-it\">Ship It</h2>\n<p>This lesson produces the <code>skill-catalog-builder</code> bundle. It scans explicitly ordered roots, rejects symlinked entry files and name-directory mismatches, resolves cross-scope collisions, rejects equal-precedence duplicates, and fits selected metadata into declared entry, description, and serialized-character budgets.</p>\n<p>Its JSON report contains selected entries, shadowed candidates, omitted entries, validation errors, precedence, and budget use. Body and reference loading remain separate runtime operations, so the catalog builder does not execute scripts or admit the whole package into context.</p>\n<h2 id=\"exercises\">Exercises</h2>\n<ol>\n<li>Add a plugin scope and place it between user and built-in precedence. Prove the collision result with a test.</li>\n<li>Change the collision policy from highest precedence to qualified names. Preserve both entries in the catalog.</li>\n<li>Add a byte-size limit to <code>load_reference</code>. Test a file exactly at the limit and one byte above it.</li>\n<li>Create two descriptions that sound nearly identical. Rewrite them so the trigger boundaries do not overlap.</li>\n<li>Add a manifest containing hashes for every reference and script. Detect a modified resource before loading it.</li>\n<li>Instrument the demo to report Level 1, Level 2, and Level 3 byte counts separately.</li>\n</ol>\n<h2 id=\"key-terms\">Key Terms</h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Term</th><th>What people say</th><th>What it actually means</th></tr></thead><tbody><tr><td>Skill discovery</td><td>&quot;Find every SKILL.md&quot;</td><td>Search configured scopes, validate packages, attach provenance, and apply policy</td></tr><tr><td>Skill catalog</td><td>&quot;The list of installed skills&quot;</td><td>Compact model-visible routing metadata for eligible packages</td></tr><tr><td>Collision policy</td><td>&quot;Which duplicate wins&quot;</td><td>A declared rule for same-name candidates from different sources</td></tr><tr><td>Progressive disclosure</td><td>&quot;Lazy loading&quot;</td><td>Staged context admission from catalog to body to branch-specific resources</td></tr><tr><td>Reference graph</td><td>&quot;Files linked by the skill&quot;</td><td>The reachable resource structure and its load conditions</td></tr><tr><td>Path containment</td><td>&quot;Stay in the folder&quot;</td><td>Verify resolved resource targets remain inside the resolved package root</td></tr></tbody></table></div>\n<h2 id=\"further-reading\">Further Reading</h2>\n<ul>\n<li><a href=\"https://agentskills.io/specification\" target=\"_blank\" rel=\"noopener\">Agent Skills specification</a> for package shape and progressive disclosure levels.</li>\n<li><a href=\"https://agentskills.io/skill-creation/optimizing-descriptions\" target=\"_blank\" rel=\"noopener\">Optimizing skill descriptions</a> for catalog routing metadata.</li>\n<li><a href=\"https://agentskills.io/skill-creation/best-practices\" target=\"_blank\" rel=\"noopener\">Agent Skills best practices</a> for direct references and entry-file size.</li>\n<li><a href=\"https://learn.chatgpt.com/docs/build-skills\" target=\"_blank\" rel=\"noopener\">OpenAI: Build skills</a> for current Codex discovery scopes and catalog limits.</li>\n</ul>","quiz":[{"correct":0,"options":["The host's documented scope-precedence policy","The directory with the newest timestamp","The longest SKILL.md body","The skill description's first verb"],"q":"A host finds the same skill name in project and user scopes. What determines which one wins?","stage":"pre","why":"The portable skill format does not create one universal precedence order. A host must declare how scopes shadow one another and should report collisions instead of silently relying on filesystem iteration order."},{"correct":1,"options":["Every script, asset, and reference in full","A compact identity record such as name and description","The output from running every bundled script","Only the modification timestamp"],"q":"What belongs in the first discovery catalog sent to a model before implementation?","stage":"check","why":"Level-one discovery should carry enough metadata to route a task without loading full instructions. Bodies and referenced resources are disclosed later, which protects the context budget and avoids premature execution."},{"correct":3,"options":["Load all bodies, discard most, then build a catalog","Read references first, then infer which skill owns them","Run scripts, load assets, then discover names","Catalog metadata, load the selected SKILL.md body, then read a needed reference"],"q":"Which sequence correctly implements progressive disclosure under this contract?","stage":"check","why":"Discovery, activation, and resource loading are separate stages. Each stage spends more context only after the previous stage establishes relevance, so unrelated skill bodies and references remain outside the prompt."},{"correct":0,"options":["Because choosing by incidental directory order makes routing nondeterministic and hard to audit","Because every collision means both skills are invalid YAML","Because duplicate names automatically receive network access","Because the user scope must always win"],"q":"Why should an equal-precedence duplicate be reported as ambiguous?","stage":"check","why":"If two candidates have the same name and policy rank, lexical or iteration order is not meaningful authority. Failing clearly forces the host or user to resolve identity instead of producing environment-dependent behavior."},{"correct":2,"options":["Copy the file to a global cache automatically","Execute it to discover whether it is useful","Reject it as a deeper reference chain than the package contract allows","Follow it because every relative path is safe"],"q":"A SKILL.md references `references/archive/schema.md` in a bundle that permits only one-level references. What should validation do?","stage":"post","why":"A one-level contract allows direct files or paths such as `references/schema.md`, not recursively nested chains. The bound keeps packages inspectable and blocks traversal-like complexity before content is loaded."},{"correct":0,"options":["Apply deterministic limits, report omitted entries, and allow narrower discovery","Ignore the budget whenever a skill has a long description","Remove skill names while keeping full instruction bodies","Randomly sample entries on every run"],"q":"What is the most defensible response when a catalog exceeds its declared context budget?","stage":"post","why":"Deterministic truncation or omission makes catalog behavior reproducible and measurable. Reporting omissions preserves observability, while narrower scope or search can retrieve candidates that did not fit the first catalog."}],"toc":[[2,"learning-objectives","Learning Objectives"],[2,"the-problem","The Problem"],[2,"the-concept","The Concept"],[3,"discovery-is-a-compiler-pipeline","Discovery is a compiler pipeline"],[3,"scope-is-runtime-policy","Scope is runtime policy"],[3,"collisions-need-identity-beyond-name","Collisions need identity beyond name"],[3,"three-disclosure-levels","Three disclosure levels"],[3,"branch-specific-references-beat-topic-dumps","Branch-specific references beat topic dumps"],[3,"catalog-budget-and-active-context-are-different-budgets","Catalog budget and active context are different budgets"],[3,"resource-paths-are-a-trust-boundary","Resource paths are a trust boundary"],[3,"loading-must-be-observable","Loading must be observable"],[2,"build-it","Build It"],[3,"why-discovery-is-shallow","Why discovery is shallow"],[3,"why-the-lab-does-not-parse-arbitrary-yaml","Why the lab does not parse arbitrary YAML"],[2,"use-it","Use It"],[2,"ship-it","Ship It"],[2,"exercises","Exercises"],[2,"key-terms","Key Terms"],[2,"further-reading","Further Reading"]]});
